/*selectMasterWmGiMultiReleaseTransPopList*/ SELECT PODT.BUYER, PODT.PO_NO, PODT.PO_SEQ, PODT.BUYER_ITEM_NO, POHD.PO_CREATE_DATE, PODT.RD_DATE, IVDT.INV_NO, IVDT.INV_SEQ, PODT.DESCRIPTION, PODT.SPECIFICATION, NVL(IVDT.WMS_GR_QTY, 0) - NVL(IVDT.WMS_IVK_QTY, 0) AS WMS_GW_QTY, NVL(IVDT.BOX_QTY, 1) AS BOX_QTY, DECODE(IVDT.CAR_ID, NULL, 0, '', 0, 1) AS CAR_NO_IMG, IVDT.CAR_ID, IVDT.CAR_NO, IVDT.CAR_PERSON_NAME, IVDT.CAR_PERSON_TEL, PODT.BYIT_COMORG_CODE, PODT.CONTRACT_NO, PODT.CONTRACT_SEQ FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMIVDT IVDT, KEP_BUYER_FLAG FLAG WHERE 1=1 AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.BUYER = FLAG.COM_CODE(+) AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND IVDT.WMS_GR_QTY != 0 AND IVDT.WMS_GR_QTY <> IVDT.WMS_IVK_QTY AND PODT.ITEM_QTY > PODT.IV_QTY AND F_GET_CREDIT_LIMIT_STTS(PODT.BUYER,'','','2') = 'N' AND PODT.PROCESS_TYPE = '2' AND FLAG.INVOICE_PRINT_FLAG(+) != 'Y'
AND PODT.BUYER = #{st_buyer} AND PODT.WAREHOUSE_CODE = #{st_warehouse_code}
AND PODT.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND IVDT.SCHEDULED_DATE BETWEEN #{st_from_date} AND #{st_to_date}
ORDER BY IVDT.INV_NO, IVDT.INV_SEQ, PODT.PO_NO, PODT.PO_SEQ


/*selectMasterWmGiMultiReleaseTransPopCheck*/
SELECT	DECODE(#{WMS_GW_QTY}, NVL(WMS_GR_QTY, 0) - NVL(WMS_IVK_QTY, 0), 'Y', 'N') AS POSB_CHECK
FROM	ICOMIVDT
WHERE	BUYER = #{BUYER}
AND		INV_NO = #{INV_NO}
AND		INV_SEQ = #{INV_SEQ}

mapper.update:

/*updateMasterWmGiMultiReleaseTransPopICOMPODT*/
UPDATE	ICOMPODT
SET		IV_QTY = NVL(IV_QTY,0) + #{WMS_GW_QTY}
WHERE	BUYER = #{BUYER}
AND		PO_NO = #{PO_NO}
AND		PO_SEQ = #{PO_SEQ}
AND		STATUS != 'D'


/*updateMasterWmGiMultiReleaseTransPopICOMIVDT*/
UPDATE	ICOMIVDT
SET		WMS_IVK_QTY = NVL(WMS_IVK_QTY,0) + #{WMS_GW_QTY}
WHERE	BUYER = #{BUYER}
AND		INV_NO = #{INV_NO}
AND		INV_SEQ = #{INV_SEQ}
AND		STATUS != 'D'

